package com.srent.ekyc;
import com.srent.audit.AuditService; import com.srent.common.ApiException; import com.srent.security.CurrentUser; import com.srent.storage.StorageService; import com.srent.user.UserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/landlords/verification") @RequiredArgsConstructor @PreAuthorize("hasRole('LANDLORD')")
public class EkycController {
    private final LandlordVerificationRepository verifications;private final VerificationDocumentRepository documents;private final UserRepository users;private final StorageService storage;private final EkycProvider provider;private final AuditService audit;
    public record UploadRequest(@NotBlank String documentType,@NotBlank String contentType){} public record Doc(@NotBlank String documentType,@NotBlank String objectKey,@NotBlank String contentType){} public record Request(@NotBlank String legalName,@NotBlank @Size(min=6,max=30)String identityNumber,@NotBlank String address,@NotEmpty List<@Valid Doc>documents){} public record Response(UUID id,String legalName,String identityNumberMasked,String address,LandlordVerification.Status status,String provider,boolean simulated,String extractedData,String anomalyReasons,String adminNote,List<String>documentTypes){static Response from(LandlordVerification v,List<VerificationDocument>d){return new Response(v.getId(),v.getLegalName(),v.getIdentityNumberMasked(),v.getAddress(),v.getStatus(),v.getProvider(),v.isSimulated(),v.getExtractedData(),v.getAnomalyReasons(),v.getAdminNote(),d.stream().map(VerificationDocument::getDocumentType).toList());}}
    @PostMapping("/upload-request") public StorageService.Upload upload(@Valid @RequestBody UploadRequest q){if(!Set.of("image/jpeg","image/png","application/pdf").contains(q.contentType()))throw ApiException.badRequest("INVALID_DOCUMENT_TYPE","Chỉ hỗ trợ JPEG, PNG hoặc PDF");return storage.presignedUpload(true,"verification/"+CurrentUser.id()+"/"+UUID.randomUUID(),q.contentType());}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public Response submit(@Valid @RequestBody Request q){for(Doc d:q.documents()){if(!d.objectKey().startsWith("verification/"+CurrentUser.id()+"/"))throw ApiException.forbidden("Tài liệu không thuộc vùng upload của bạn");storage.stat(true,d.objectKey());}var result=provider.process(new EkycProvider.Input(q.legalName(),q.identityNumber(),q.address(),q.documents().stream().map(Doc::objectKey).toList()));var v=new LandlordVerification();v.setLandlord(users.getReferenceById(CurrentUser.id()));v.setLegalName(q.legalName());v.setIdentityNumberMasked(mask(q.identityNumber()));v.setAddress(q.address());v.setProvider(provider.name());v.setSimulated(provider.simulated());v.setExtractedData(result.extractedData());v.setAnomalyReasons(String.join("; ",result.anomalies()));v.setStatus(LandlordVerification.Status.NEEDS_REVIEW);verifications.save(v);for(Doc x:q.documents()){var d=new VerificationDocument();d.setVerification(v);d.setDocumentType(x.documentType());d.setObjectKey(x.objectKey());d.setContentType(x.contentType());documents.save(d);}audit.log(CurrentUser.id(),"VERIFICATION_SUBMITTED","LANDLORD_VERIFICATION",v.getId(),"provider="+provider.name());return Response.from(v,documents.findAllByVerificationId(v.getId()));}
    @GetMapping("/me") public Response mine(){var v=verifications.findFirstByLandlordIdOrderByCreatedAtDesc(CurrentUser.id()).orElseThrow(()->ApiException.notFound("Hồ sơ xác minh"));return Response.from(v,documents.findAllByVerificationId(v.getId()));}
    private static String mask(String s){return "*".repeat(Math.max(0,s.length()-4))+s.substring(Math.max(0,s.length()-4));}
}
